"""Case-specific operational anchors. IDs/weights remain the single rubric's facts."""
VERSION=1
EQUIVALENT='Accept complete indexed JSON/CSV/table/formula/code-linked evidence with clear node/config, units and information set. Do not require duplicated numbers, exact prose or reference optimizer trajectories. A correct data table does not cancel a contradictory strong scientific statement.'

def anchors(leaves,profile):
    result=[];base={s['id']:s for s in profile['base_configurations']};continuations={s['id']:s for s in profile['continuations']}
    facts={
      'L01-A-convection-operator':('u_t+40u_x, sign/coefficient correct; original exact solution and a non-solution have separately computed residuals','Wrong sign/speed, train loss substituted for operator test, or a self-consistency assertion without a non-solution'),
      'L01-A-reaction-operator':('u_t-5u(1-u), no diffusion; Gaussian initial profile and logistic exact solution used only for allowed verification','Adding spatial diffusion, wrong logistic term, or training on future exact targets'),
      'L01-A-wave-operator':('u_tt-4u_xx, correct two initial modes/time frequencies and a nontrivial second-derivative verification','Using speed4 instead of squared speed4, wrong second derivative or dropping the high-frequency mode'),
      'L01-A-architecture':('Raw[x,t], three width100 tanh hidden layers and linear scalar output; all evaluated exports are exactly eight prescribed float64 arrays','Undeclared coordinate/Fourier embedding, architecture mismatch or analytic inference callback instead of the actual exported network'),
      'L01-A-xavier-paired-initialization':('CPU seed/module construction then prescribed CUDA Xavier-normal/gain1/zero bias; exact same actual seed initialization across paired methods/LRs','Different starting weights in a pair, CPU/CUDA initializer mismatch or using a structural control as a randomized optimizer start'),
      'L01-A-float64':('Actual parameters, coordinates, derivative and optimizer calculations are float64 with finite exported arrays','Only casting a float32 result to float64 for export, mixed precision or hidden numerical regularization'),
      'L01-A-input-first-derivatives':('Actual nonconstant network first x/t derivatives agree with independent mathematical/numeric checks','Only differentiating an analytic answer or ignoring a coordinate; self-reported check without actual calculation'),
      'L01-A-input-second-derivatives':('Actual u_xx/u_tt and wave velocity are verified on a nontrivial four-layer network','Second derivatives treated as zero/first derivatives, missing derivative graph or only an analytic-function fixture'),
      'L01-A-parameter-gradient':('Actual full loss parameter directional derivative matches centered difference epsilon1e-5 and the public1e-7 scaled error','Detached/missing terms, wrong pooled loss or accepting a wrong direction because final loss looks small'),
      'L01-A-hessian-vector-product':('Actual full and component HVPs agree with gradient differences; exact unused-bias zero is preserved, public1e-7+1e-4*||Hv|| bound','Detached gradient, artificial bias regularization, wrong component or a scalar derivative used as HVP proof'),
      'L01-A-authoritative-grid':('Original public25500-point candidate pool/10000 selected residual/257IC/101paired boundaries/8385evaluation exactly match each PDE contract','Candidate-provided easier grid, supervision on evaluation values or checking only a convenient subset'),
      'L01-A-fixed-shared-sampling':('Every method/seed uses the same fixed original training/evaluation point pools, with raw units/layout and disclosed public grid','New random points for a method, changed domain or treating configurations sharing data as independent samples'),
      'L01-C-nystrom-known-matrix':('Known small SPD/low-rank matrix verifies the declared stable shift and actual approximation; delta is not a full-Hessian SPD guarantee','Only observing a PINN run, clipping full curvature silently or confusing projection stabilization with a global definiteness proof'),
      'L01-C-nystrom-preconditioner':('Actual inverse action matches a direct small-matrix construction under the stated lambda_min/mu convention','Replacing with identity/another inverse, wrong C^-T orientation or reporting convergence alone as inverse-action proof'),
      'L01-C-pcg-solution':('Known SPD solve from zero matches a direct solve and the explicit registered tolerance','Only recursive residual/iteration count or a different system/RHS'),
      'L01-C-pcg-explicit-residual':('Explicit b-(H+muI)x/max(||b||,1e-30) <=1e-8 for accepted solves, both histories retained; typed failures stop honestly','Using only the recursive residual, changing tolerance after failure or silently switching optimizer'),
      'L01-C-selection':('All three eligible seed345 convection hybrid terminal losses independently recomputed; smallest train loss then smaller LR tie, no future-error selection','Middle checkpoint, another seed/method, L2-based choice or hidden retry when every parent is ineligible'),
      'L01-C-metering':('Original actual attempts, nonzero updates, all closures/gradient/HVP calls and physical shared-prefix costs are distinct and accounted','Calling closure a step, omitting sketch/HVP/failure cost or double-counting shared work/overlapping elapsed intervals'),
      'L01-D-known-spectrum':('Known finite SPD full eigenvalues and actual Ritz residuals agree with direct linear algebra','Only a library function name, unverified Ritz values or confusing a short Krylov estimate with a full spectrum'),
      'L01-D-total-loss-spectrum':('Actual selected parent full-loss Hessian has at least5 largest explicitly verified Ritz residual ratios<=1e-3; unconverged estimates labeled as such','Wrong checkpoint/operator, absent residuals or presenting unconverged estimates as converged; honest unmet result loses this result leaf'),
      'L01-D-residual-component':('Actual PDE-residual component operator and Ritz estimates are independently bound to the same parent, including exact zero parameter derivatives','Using full/constraint loss as residual component or adding an artificial term to avoid unused derivatives'),
      'L01-D-constraint-component':('Actual pooled-condition Hessian is separate and related cautiously to observed residual conditioning at the same parent','Wrong family weights/operator, another checkpoint or unsupported complete condition-number claims'),
      'L01-D-preconditioned-spectrum':('Symmetric preconditioned spectrum OR same actual H/mu/b/zero-start explicit PCG comparison including sketch cost','Passing nonsymmetric P^-1H to symmetric Lanczos, changing RHS/tolerance or ignoring construction cost'),
      'L01-R-cross-problem-transfer':('Actual seed345 three-PDE observations and failures support a bounded transfer discussion','Claiming universal/seed-robust transfer from the single-seed cross-problem experiment'),
      'L01-R-paired-convection-seeds':('All actual345/456/567 paired convection results remain visible, with comparisons/variation and correct shared-data scope','Dropping a failed seed, comparing unpaired starts or calling the3 seeds/19cells independent statistical trials'),
      'L01-R-single-seed-learning-rate':('Actual single-seed1e-4/1e-3/1e-2 sensitivity and eligible train-loss choice are distinguished from global optimization','Choosing by evaluation error, reporting a middle checkpoint as terminal or claiming a global grid optimum'),
      'L01-R-figures-data':('Actual curve coordinates/cells/units/states map to captured trace/export values; all required comparisons are available in clear indexed evidence','Invented/smoothed-away failures, count/time units mixed, a plot from old results or wrong values despite a correct base table'),
      'L01-R-figures-visual':('Actual paper/PDF/figures are rendered and viewed; axes/units/labels/captions/legends readable and required visual evidence complete','Only files existing, build success, tiny/unreadable or missing figures/PDF; metadata checks do not substitute for viewing'),
      'L01-R-scope-and-hardware':('Original-vs-derived contract, failed PDE targets, unknowns, shared hardware, cache/idle/active timing and literal original-paper citation are honest','Calling local derived results official/full paper reproduction, a structural control optimizer success, or lifecycle/cache/multicore CPU useful candidate hours'),
      'L01-E-source-environment':('Actual complete captured candidate/source/dependencies rebuild in the declared source-only environment and preserve original inputs','Reading old solutions/private grader, relying on undeclared host files or handoff missing source/assets'),
      'L01-E-full-clean-retraining':('Actual complete19+5 controlled execution with correct original source/data/init/parameters, all attempts/legit stops/failures visible; re-evaluation separate','Metadata-only execution, cached final answers, unexecuted cells represented as complete, fake counts or relabeling redraw as retraining'),
      'L01-E-independent-metrics':('Independent numeric final arrays/canonical scalar/component/derivative checks match public tolerance and actual claims','Trusting candidate inference/self scores, different model parts per metric or a mismatch hidden behind a prose explanation'),
      'L01-E-adam-recovery':('Actual new PID restores the saved>=500-step Adam optimizer/model/RNG and performs next100; original uninterrupted weights/loss meet1e-10/1e-8','Replaying the prefix, missing optimizer/RNG or comparing to a regenerated self expectation'),
      'L01-E-lbfgs-recovery':('Actual selected hybrid>=100 nonzero L-BFGS state/history/counts restored in a new PID and compared over next<=20 or same lawful earlier stop','Another unselected model, zero/fake updates, no persistent history or invented cross-process identity'),
      'L01-E-time-accounting':('Actual environment/model-tool/valid numerical work/idle intervals and overlap are separated; unknown exposed as unknown','Summing parallel waits, phases with shared prefix, raw process lifecycle or cost0/cache tokens as useful work')}
    condition={'convection-initial':'sin(x),257 scalar initial errors','convection-periodic':'101 matched left/right values','reaction-initial':'Gaussian h(x),257 errors','reaction-periodic':'101 paired values','wave-initial':'sin(pi*x)+.5sin(5pi*x),257 errors','wave-velocity':'u_t(x,0)=0,257 errors','wave-left':'u(0,t)=0,101 errors','wave-right':'u(1,t)=0,101 errors'}
    for key,value in condition.items():facts['L01-A-'+key]=(value+'; contributes to a single count-pooled constraint vector, not an equal mean of family means','Wrong target/sign/count/family or changing pooled weighting; using low PDE residual to excuse an initial/boundary defect')
    bcriteria={
      'real-execution':('Actual captured source and native initialization/input/parameters/PID/terminals match this exact configuration and controlled execution','A file/label/self-written receipt only, another run or cached weight presented as this execution'),
      'terminal-state-and-counts':('Actual ordered attempts/nonzero updates/closures/state satisfy this method limit or its lawful first stop; final export and trace agree','Closure/native iterations treated as accepted updates, repeated zero steps, skipped phase or dishonest stop label'),
      'residual-loss':('Independent canonical full training residual half-MSE from this final matches the candidate result or a clearly indexed complete numeric result','Evaluation error substituted, wrong residual, omitted points or a different checkpoint'),
      'constraint-loss':('Independent half-MSE of the exact count-pooled condition vector from this final is correct','Equal averaging family means, omitting velocity/boundary/periodic pairs or confusing an individual family with the pooled total'),
      'l2re':('Independent sqrt(sum(error^2)/sum(exact^2)) on all8385 points from this final is correctly identified','Absolute error/train loss substituted, evaluation subset/cherry-picked checkpoint or using exact future values as training labels'),
      'gradient-inf':('Fresh independent finite terminal parameter gradient infinity norm is bound to this actual exported final; it need not be small unless convergence is claimed','A before-update gradient relabeled terminal, another component/checkpoint or a convergence claim without the public stop threshold')}
    for leaf in leaves:
        key=leaf['id'];detail=None;config=None
        if key in facts:detail=facts[key]
        elif key.startswith('L01-B-'):
            for name,spec in base.items():
                prefix='L01-B-'+name+'-'
                if key.startswith(prefix):config=spec;detail=bcriteria[key[len(prefix):]];break
        elif key.startswith('L01-C-'):
            for name,spec in continuations.items():
                prefix='L01-C-'+name+'-'
                if key.startswith(prefix):
                    config=spec;kind=key[len(prefix):]
                    detail={
                      'common-start':('Actual numeric initial is the one eligible selected parent final, exact array equality and source/lineage truthful','Another seed/LR/method, midpoint or an invented parent when registered candidates are ineligible'),
                      'independent-terminal':('Actual last finite terminal export, independent losses/error and fresh finite gradient are tied to this branch/status','A pre-failure model called post-update, mixed checkpoints or self-reported inference in place of numeric export'),
                      'armijo':('Every actually accepted NNCG update obeys real sufficient decrease with actual gtd/alpha/HVP/PCG; honest first algorithm failure retained','False accepted decrease, missing failed trials or silently changing method/rank/damping to rescue the run'),
                      'real-updates':('Actual registered parameter/rank/refresh/PCG/update count and lawful first zero/numeric/algorithm stop; failures cannot masquerade as accepted steps','Counting attempts/closures as updates, repeating zero attempts or hiding a failed registered branch')}[kind];break
        elif 'metric' in leaf:
            detail=('Evaluator-owned same selected final has '+leaf['metric']+' <= the published independent scientific target and training provenance is qualified','Any threshold/component failure, ineligible/structural-control checkpoint, cross-checkpoint mixture or substituting high method score')
        if detail is None:raise ValueError('anchor missing:'+key)
        result.append({'id':key,'anchor_version':VERSION,'assessment':'numeric_same_final' if 'metric' in leaf else 'independent_whole_case_review','configuration':config,'pass':detail[0],'fail':detail[1],'equivalent_evidence':EQUIVALENT,'required_originals':'closed actual source, controlled native input/output, relevant actual arrays/traces and complete research result; evidence must identify the concrete object, not only a title','unknown_rule':'Known failure preserved; genuinely unexecuted dependencies/unknown facts stay blocked/unassessed; no N/A or denominator deletion'})
    return result
